INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (100101, "人助けが大好き！　前向き格闘娘", 27, "人助け、応援", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "ヒヨリ", 16, 8, 155, "A", 44, "トゥインクルウィッシュ", "獣人族", "東山奈央", 0, 2);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (100201, "戦闘のサポートが得意な、心優しい少女", 5, "料理、人間観察", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "ユイ", 17, 4, 158, "O", 47, "トゥインクルウィッシュ", "ヒューマン", "種田梨沙", 0, 2);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (100301, "クールで何事にも真っ直ぐな剣士", 12, "読書、乗馬、お茶", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "レイ", 18, 1, 163, "B", 46, "トゥインクルウィッシュ", "魔族", "早見沙織", 0, 2);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (100401, "探検好きのイタズラっ子", 10, "いたずら、探検", "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", "ミソギ", 9, 8, 128, "O", 27, "リトルリリカル", "ヒューマン", "諸星すみれ", 0, 5);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (100501, "ヒーローに憧れる騎士見習いの少女", 25, "ヒーローごっこ", "？？？", "マツリ", 12, 11, 146, "O", 40, "王宮騎士団（NIGHTMARE）", "獣人族", "下田麻美", 0, 8);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (100601, "甘え上手なみんなの人気者", 22, "サックス", "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", "アカリ", 13, 11, 150, "O", 42, "悪魔偽王国軍（ディアボロス）", "魔族", "浅倉杏美", 0, 7);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (100701, "プリン大好きゴースト娘", 23, "プリンを食べること", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", "ミヤコ", 14, 1, 130, "B", 32, "悪魔偽王国軍（ディアボロス）", "魔族", "雨宮天", 0, 7);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (100801, "ボクは誰よりも美しい", 10, "鏡で自分を見ること", "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", "ユキ", 14, 10, 150, "AB", 40, "ヴァイスフリューゲル　ランドソル支部", "エルフ", "大空直美", 0, 15);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (100901, "前世を信じる中二病患者、「疾風の冥姫」", 5, "小説執筆", "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", "アンナ", 17, 7, 159, "A", 45, "トワイライトキャラバン", "魔族", "髙野麻美", 0, 13);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (101001, "マホマホ王国のプリンセス", 22, "空想、ぬいぐるみ集め", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", "マホ", 16, 9, 155, "O", 42, "自警団（カォン）", "獣人族", "内田真礼", 0, 10);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (101101, "人懐っこくてマシンガントークな妹系少女", 25, "お裁縫", "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", "リノ", 15, 8, 156, "A", 44, "ラビリンス", "ヒューマン", "阿澄佳奈", 0, 3);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (101201, "みんなのために超能力を使う眠り姫", 24, "妹と遊ぶこと、二度寝、昼寝、早寝", "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", "ハツネ", 17, 12, 156, "A", 46, "フォレスティエ", "エルフ", "大橋彩香", 0, 6);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (101301, "オタク全開な魔法少女", 21, "読書、魔法", "", "ナナカ", 18, 8, 166, "O", 55, "トワイライトキャラバン", "魔族", "佳村はるか", 0, 13);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (101401, "頭脳明晰な美少女名探偵", 3, "読書、推理", "test", "カスミ", 15, 11, 152, "AB", 41, "自警団（カォン）", "獣人族", "水瀬いのり", 0, 10);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (101501, "母性溢れる優しいみんなの「ミサト先生」", 5, "絵本作り", "test", "ミサト", 21, 9, 165, "O", 54, "フォレスティエ", "エルフ", "國府田マリ子", 0, 6);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (101601, "天真爛漫で人気者のカリスマモデル", 10, "ファッション", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", "スズナ", 17, 4, 167, "O", 48, "ルーセント学院", "魔族", "上坂すみれ", 0, 14);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (101701, "いつでも「なんくるないさ～」な天然娘", 7, "踊り、空手", "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", "カオリ", 17, 7, 158, "A", 53, "自警団（カォン）", "獣人族", "高森奈津美", 0, 10);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (101801, "多くの男性を魅了する無垢な女教師", 14, "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", "イオ", 23, 8, 162, "B", 52, "ルーセント学院", "魔族", "伊藤静", 0, 14);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (102001, "お歌もにんじんも、ウサギさんも大好き♪", 3, "かわいいもの集め", "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", "ミミ", 10, 4, 117, "O", 21, "リトルリリカル", "獣人族", "日高里菜", 0, 5);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (102101, "泣き虫で臆病な守ってあげたい女の子", 9, "観劇、おままごと", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "クルミ", 12, 6, 150, "B", 40, "サレンディア救護院", "ヒューマン", "植田佳奈", 0, 9);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (102201, "人見知りであまのじゃくな女の子", 22, "ゲーム全般", "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", "ヨリ", 13, 11, 150, "O", 40, "悪魔偽王国軍（ディアボロス）", "魔族", "原紗友里", 0, 7);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (102301, "ぷうきちといつも一緒！", 10, "屋内でできる遊び", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", "アヤネ", 14, 5, 148, "B", 38, "サレンディア救護院", "ヒューマン", "芹澤優", 0, 9);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (102501, "お嬢さまのためにがんばるドジっ娘メイド", 12, "ご奉仕", "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", "スズメ", 15, 12, 154, "O", 43, "サレンディア救護院", "ヒューマン", "悠木碧", 0, 9);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (102601, "遊びと睡眠が何より大事なぐうたら娘", 1, "あんパン", "test", "リン", 17, 1, 144, "B", 42, "牧場（エリザベスパーク）", "獣人族", "小岩井ことり", 0, 11);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (102701, "運命の相手に一途すぎる乙女", 30, "実験、裁縫、料理", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "エリコ", 16, 7, 154, "B", 43, "トワイライトキャラバン", "魔族", "橋本ちなみ", 0, 13);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (102801, "救護院を経営する優しい庶民派お嬢様", 4, "経営、お茶会", "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", "サレン", 17, 10, 156, "A", 43, "サレンディア救護院", "エルフ", "堀江由衣", 0, 9);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (102901, "歌って踊れる大人気アイドル", 24, "舞台鑑賞、ダンス", "いつか世界中の人達をファンにしてみせる！\nトップアイドルになるその日まで、\n応援よろしくね♪", "ノゾミ", 17, 1, 157, "B", 40, "カルミナ", "ヒューマン", "日笠陽子", 0, 4);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (103001, "トーゴクの神秘、オシエテクダサイ！", 31, "忍法開発", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", "ニノン", 16, 8, 163, "O", 51, "ヴァイスフリューゲル　ランドソル支部", "ヒューマン", "佐藤聡美", 0, 15);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (103101, "占いが得意な霊能少女", 22, "占い", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "シノブ", 18, 12, 157, "AB", 42, "悪魔偽王国軍（ディアボロス）", "魔族", "大坪由佳", 0, 7);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (103201, "一人前の商人を目指すパワフルお嬢様", 12, "慈善事業", "この私とともにいる限り、\nお金に不自由はさせませんわ！", "アキノ", 18, 3, 157, "AB", 45, "メルクリウス財団", "ヒューマン", "松嵜麗", 0, 12);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (103301, "みんなを笑顔にするお笑い牧場主", 3, "漫才", "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", "マヒル", 20, 3, 142, "B", 35, "牧場（エリザベスパーク）", "ヒューマン", "新田恵海", 0, 11);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (103401, "純情でほっとけない大人の女性", 16, "ウインドーショッピング", "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", "ユカリ", 22, 3, 164, "A", 55, "メルクリウス財団", "エルフ", "今井麻美", 0, 12);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (103601, "礼儀正しくしっかり者のちびっ子優等生", 2, "お勉強", "test", "キョウカ", 8, 2, 118, "A", 21, "リトルリリカル", "エルフ", "小倉唯", 0, 5);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (103701, "義理堅くてからかい好きな剣術少女", 11, "剣術、年長者をからかう", "test", "トモ", 13, 8, 149, "A", 43, "王宮騎士団（NIGHTMARE）", "ヒューマン", "茅原実里", 0, 8);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (103801, "読書が趣味の病弱少女", 3, "読書、お散歩", "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", "シオリ", 14, 11, 153, "A", 40, "牧場（エリザベスパーク）", "獣人族", "小清水亜美", 0, 11);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (104001, "「友達」に憧れる、エルフの森の女の子", 6, "友達作りのイメトレ", "友達ができるその日まで…\nBB団で\nトレーニングですっ！", "アオイ", 13, 6, 158, "AB", 44, "フォレスティエ", "エルフ", "花澤香菜", 0, 6);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (104201, "人々を守るために歌う、唱喚士の少女", 3, "各種楽器", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "チカ", 17, 6, 163, "O", 46, "カルミナ", "ヒューマン", "福原綾香", 0, 4);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (104301, "男勝りで情に厚いワイルド娘", 9, "お菓子作り", "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", "マコト", 17, 8, 168, "O", 54, "自警団（カォン）", "獣人族", "小松未可子", 0, 10);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (104401, "かつては夜を支配した最強の吸血鬼", 5, "世界征服", "test", "イリヤ", "??", 5, 172, "A", 50, "悪魔偽王国軍（ディアボロス）", "魔族", "丹下桜", 0, 7);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (104501, "妄想大好き！　ほんとは照れ屋な女の子", 19, "小説を読むこと", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", "クウカ", 18, 11, 157, "AB", 49, "ヴァイスフリューゲル　ランドソル支部", "ヒューマン", "長妻樹里", 0, 15);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (104601, "弱きを助け強きをくじく猫娘", 1, "猫とたわむれること", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "タマキ", 19, 3, 158, "AB", 48, "メルクリウス財団", "獣人族", "沼倉愛美", 0, 12);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (104701, "素顔を見せない冷静沈着な女性騎士", 25, "格闘技、湯浴み", "？？？", "ジュン", 25, 10, 171, "A", 50, "王宮騎士団（NIGHTMARE）", "ヒューマン", "川澄綾子", 0, 8);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (104801, "仕事も私事も効率優先な傭兵少女", 11, "傭兵などのアルバイト", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", "ミフユ", 20, 11, 163, "O", 49, "メルクリウス財団", "ヒューマン", "田所あずさ", 0, 12);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (104901, "お姉ちゃんがお世話してあげるからねっ！", 24, "家事全般", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "シズル", 18, 10, 168, "O", 54, "ラビリンス", "ヒューマン", "生天目仁美", 0, 3);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (105001, "ちょっとおませな恋に恋する女の子", 3, "ファッション誌鑑賞、コスメ集め", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", "ミサキ", 11, 1, 120, "A", 22, "ルーセント学院", "魔族", "久野美咲", 0, 14);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (105101, "実験が趣味の危険な科学者", 7, "研究、実験", "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", "ミツキ", 27, 3, 166, "A", 53, "トワイライトキャラバン", "ヒューマン", "三石琴乃", 0, 13);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (105201, "乙女チックなもふもふアニマル", 14, "毛繕い、お喋り", "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…", "リマ", 17, 3, 150, "A", 100, "牧場（エリザベスパーク）", "獣人族", "徳井青空", 0, 11);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (105301, "見た目も中身もお子ちゃまな異国の軍人", 28, "お菓子屋通い", "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", "モニカ", 17, 7, 140, "A", 33, "ヴァイスフリューゲル　ランドソル支部", "ヒューマン", "辻あゆみ", 0, 15);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (105401, "ファッション大好きなキュートガール", 7, "裁縫", "test", "ツムギ", 14, 9, 153, "AB", 45, "カルミナ", "ヒューマン", "木戸衣吹", 0, 4);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (105501, "どこまでも一途に慕う、純情乙女", 7, "観察", "test", "アユミ", 16, 4, 155, "O", 43, "ヴァイスフリューゲル　ランドソル支部", "エルフ", "大関英里", 0, 15);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (105601, "人情味溢れる粋でいなせな「姉御」", 11, "釣り", "test", "ルカ", 25, 7, 167, "B", 54, "トワイライトキャラバン", "ヒューマン", "佐藤利奈", 0, 13);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (105701, "空への冒険を夢見る騎空士の少女", 10, "冒険、おしゃべり", "私ね、一人前の騎空士になりたいんだ\nいつか父さんみたいな騎空士になって、\n空の果てまで旅する。それが私の夢だよ！", "ジータ", 17, 3, 156, "O", 45, "？？？", "ヒューマン", "金元寿子", 0, "");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (105801, "いつも元気な腹ペコ少女", 31, "食べ歩き、料理", "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", "ペコリーヌ", 17, 3, 156, "O", 46, "美食殿", "ヒューマン", "M・A・O", 0, 1);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (105901, "主を慕う、小さなガイド役", 11, "瞑想、動植物の飼育", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "コッコロ", 11, 5, 140, "B", 35, "美食殿", "エルフ", "伊藤美来", 0, 1);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (106001, "行き倒れの謎のネコミミ魔法使い", 2, "猫と遊ぶ", "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", "キャル", 14, 9, 152, "A", 39, "美食殿", "獣人族", "立花理香", 0, 1);
