INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (107101, "傍若無人な王宮騎士団副団長", 7, "強敵との闘争", "", "クリスティーナ", 27, 2, 165, "O", "??", "王宮騎士団（NIGHTMARE）", "ヒューマン", "たかはし智秋", 0, 8);
