INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (107701, "お嬢さまのためにがんばるドジっ娘メイド", 12, "ご奉仕", "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", "スズメ（サマー）", 15, 12, 154, "O", 43, "サレンディア救護院", "ヒューマン", "悠木碧", 0, 9);
