INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (107901, "弱きを助け強きをくじく猫娘", 1, "猫とたわむれること", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "タマキ（サマー）", 19, 3, 158, "AB", 48, "メルクリウス財団", "獣人族", "沼倉愛美", 0, 12);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (108001, "仕事も私事も効率優先な傭兵少女", 11, "傭兵などのアルバイト", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", "ミフユ（サマー）", 20, 11, 163, "O", 49, "メルクリウス財団", "ヒューマン", "田所あずさ", 0, 12);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (108101, "占いが得意な霊能少女", 22, "占い", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "シノブ（ハロウィン）", 18, 12, 157, "AB", 42, "悪魔偽王国軍（ディアボロス）", "魔族", "大坪由佳", 0, 7);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (108201, "プリン大好きゴースト娘", 23, "プリンを食べること", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", "ミヤコ（ハロウィン）", 14, 1, 130, "B", 32, "悪魔偽王国軍（ディアボロス）", "魔族", "雨宮天", 0, 7);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (108301, "ちょっとおませな恋に恋する女の子", 3, "ファッション誌鑑賞、コスメ集め", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", "ミサキ（ハロウィン）", 11, 1, 120, "A", 22, "ルーセント学院", "魔族", "久野美咲", 0, 14);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (108401, "人々を守るために歌う、唱喚士の少女", 3, "各種楽器", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "チカ（クリスマス）", 17, 6, 163, "O", 46, "カルミナ", "ヒューマン", "福原綾香", 0, 4);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (108501, "泣き虫で臆病な守ってあげたい女の子", 9, "観劇、おままごと", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "クルミ（クリスマス）", 12, 6, 150, "B", 40, "サレンディア救護院", "ヒューマン", "植田佳奈", 0, 9);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (108601, "ぷうきちといつも一緒！", 10, "屋内でできる遊び", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", "アヤネ（クリスマス）", 14, 5, 148, "B", 38, "サレンディア救護院", "ヒューマン", "芹澤優", 0, 9);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (108701, "人助けが大好き！　前向き格闘娘", 27, "人助け、応援", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "ヒヨリ（ニューイヤー）", 16, 8, 155, "A", 44, "トゥインクルウィッシュ", "獣人族", "東山奈央", 0, 2);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (108801, "戦闘のサポートが得意な、心優しい少女", 5, "料理、人間観察", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "ユイ（ニューイヤー）", 17, 4, 158, "O", 47, "トゥインクルウィッシュ", "ヒューマン", "種田梨沙", 0, 2);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (108901, "クールで何事にも真っ直ぐな剣士", 12, "読書、乗馬、お茶", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "レイ（ニューイヤー）", 18, 1, 163, "B", 46, "トゥインクルウィッシュ", "魔族", "早見沙織", 0, 2);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (109001, "運命の相手に一途すぎる乙女", 30, "実験、裁縫、料理", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "エリコ（バレンタイン）", 16, 7, 154, "B", 43, "トワイライトキャラバン", "魔族", "橋本ちなみ", 0, 13);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (109101, "お姉ちゃんがお世話してあげるからねっ！", 24, "家事全般", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "シズル（バレンタイン）", 18, 10, 168, "O", 54, "ラビリンス", "ヒューマン", "生天目仁美", 0, 3);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (109201, "英霊と契約を結んだマナリアの天才王女", 1, "読書", "私はアン！一応、マナリア王国の\n第一王女だけど…あまりかしこまらないで、\n気軽に仲良くしてくれたら嬉しいな！", "アン", 17, 12, 156, "AB", 55, "？？？", "ヒューマン", "日笠陽子", 0, "");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (109301, "マナリア魔法学院の新入生", 4, "食べること、眠ること", "ルゥはルゥですぅ！マナリア魔法学院に\n通ってるですぅ。あなたもルゥの\nお友だちになってくれるですか？", "ルゥ", 16, 2, 144, "O", 45, "？？？", "ヒューマン", "こやまきみこ", 0, "");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (109401, "人を超越した力を有す心優しい竜姫", 3, "ピアノ", "私はグレア。竜と人、両方の血を\n受け継いでいるの…\nえっと…よ、よろしくね", "グレア", 17, 11, 167, "B", 67, "？？？", "半人半竜", "福原綾香", 0, "");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (109501, "妄想大好き！　ほんとは照れ屋な女の子", 19, "小説を読むこと", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", "クウカ（オーエド）", 18, 11, 157, "AB", 49, "ヴァイスフリューゲル　ランドソル支部", "ヒューマン", "長妻樹里", 0, 15);
