INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (114401, "一人前の商人を目指すパワフルお嬢様", 12, "慈善事業", "この私とともにいる限り、\nお金に不自由はさせませんわ！", "アキノ（クリスマス）", 18, 3, 157, "AB", 45, "メルクリウス財団", "ヒューマン", "松嵜麗", 0, 12);
