INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (115501, "主を慕う、小さなガイド役", 11, "瞑想、動植物の飼育", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "コッコロ（儀装束）", 11, 5, 140, "B", 35, "美食殿", "エルフ", "伊藤美来", 0, 1);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (115601, "戦闘のサポートが得意な、心優しい少女", 5, "料理、人間観察", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "ユイ（儀装束）", 17, 4, 158, "O", 47, "トゥインクルウィッシュ", "ヒューマン", "種田梨沙", 0, 2);
