INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (115801, "乙女チックなもふもふアニマル", 14, "毛繕い、お喋り", "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…", "リマ（シンデレラ）", 17, 3, 150, "A", 100, "牧場（エリザベスパーク）", "獣人族", "徳井青空", 0, 11);
