INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (116601, "拳で語る喧嘩屋ドラゴン少女", 25, "格闘技", "", "カヤ（タイムトラベル）", 16, 6, 156, "B", "???", "ドラゴンズネスト", "ドラゴン族", "小市眞琴", 0, 17);
