INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (116801, "弱きを助け強きをくじく猫娘", 1, "猫とたわむれること", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "タマキ（作業服）", 19, 3, 158, "AB", 48, "メルクリウス財団", "獣人族", "沼倉愛美", 0, 12);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (116901, "仕事も私事も効率優先な傭兵少女", 11, "傭兵などのアルバイト", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", "ミフユ（作業服）", 20, 11, 163, "O", 49, "メルクリウス財団", "ヒューマン", "田所あずさ", 0, 12);
