INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (117101, "お姉ちゃんがお世話してあげるからねっ！", 24, "家事全般", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "シズル（サマー）", 18, 10, 168, "O", 54, "ラビリンス", "ヒューマン", "生天目仁美", 0, 3);
