INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (117301, "人々を守るために歌う、唱喚士の少女", 3, "各種楽器", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "チカ（サマー）", 17, 6, 163, "O", 46, "カルミナ", "ヒューマン", "福原綾香", 0, 4);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (117401, "ファッション大好きなキュートガール", 7, "裁縫", "", "ツムギ（サマー）", 14, 9, 153, "AB", 45, "カルミナ", "ヒューマン", "木戸衣吹", 0, 4);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (117501, "実験が趣味の危険な科学者", 7, "研究、実験", "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", "ミツキ（オーエド）", 27, 3, 166, "A", 53, "トワイライトキャラバン", "ヒューマン", "三石琴乃", 0, 13);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (117601, "ボクは誰よりも美しい", 10, "鏡で自分を見ること", "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", "ユキ（オーエド）", 14, 10, 150, "AB", 40, "ヴァイスフリューゲル　ランドソル支部", "エルフ", "大空直美", 0, 15);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (117701, "いつでも「なんくるないさ～」な天然娘", 7, "踊り、空手", "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", "カオリ（ハロウィン）", 17, 7, 158, "A", 53, "自警団（カォン）", "獣人族", "高森奈津美", 0, 10);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (117801, "トーゴクの神秘、オシエテクダサイ！", 31, "忍法開発", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", "ニノン（ハロウィン）", 16, 8, 163, "O", 51, "ヴァイスフリューゲル　ランドソル支部", "ヒューマン", "佐藤聡美", 0, 15);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (117901, "天真爛漫で人気者のカリスマモデル", 10, "ファッション", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", "スズナ（ハロウィン）", 17, 4, 167, "O", 48, "ルーセント学院", "魔族", "上坂すみれ", 0, 14);
