INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (119001, "多くの男性を魅了する無垢な女教師", 14, "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", "イオ（ノワール）", 23, 8, 162, "B", 52, "ルーセント学院", "魔族", "伊藤静", 0, 14);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (119101, "妄想大好き！　ほんとは照れ屋な女の子", 19, "小説を読むこと", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", "クウカ（ノワール）", 18, 11, 157, "AB", 49, "ヴァイスフリューゲル　ランドソル支部", "ヒューマン", "長妻樹里", 0, 15);
