INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (121301, "泣き虫で臆病な守ってあげたい女の子", 9, "観劇、おままごと", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "クルミ（ステージ）", 12, 6, 150, "B", 40, "サレンディア救護院", "ヒューマン", "植田佳奈", 0, 9);
