INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (121901, "前世を信じる中二病患者、「疾風の冥姫」", 5, "小説執筆", "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", "アンナ（パイレーツ）", 17, 7, 159, "A", 45, "トワイライトキャラバン", "魔族", "髙野麻美", 0, 13);
