INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (122401, "人助けが大好き！　前向き格闘娘", 27, "人助け、応援", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "ヒヨリ（サマー）", 16, 8, 155, "A", 44, "トゥインクルウィッシュ", "獣人族", "東山奈央", 0, 2);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (122501, "クールで何事にも真っ直ぐな剣士", 12, "読書、乗馬、お茶", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "レイ（サマー）", 18, 1, 163, "B", 46, "トゥインクルウィッシュ", "魔族", "早見沙織", 0, 2);
