INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (125201, "見た目も中身もお子ちゃまな異国の軍人", 28, "お菓子屋通い", "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", "モニカ（カフェ）", 17, 7, 140, "A", 33, "ヴァイスフリューゲル　ランドソル支部", "ヒューマン", "辻あゆみ", 0, 15);
